 return f'<button class="gallery-image-button" data-full="/assets/{name}-1600.webp" data-caption="{escape(caption)}" data-source="{source}" aria-label="View {escape(caption)}">{img(name,sizes="(max-width: 650px) 90vw, 33vw")}</button>'
